={{ (() => {
  const arg = () => { const d = new Date(); return d.toLocaleDateString('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' }); };
  const base = () => { const p = arg().split('-'); return new Date(+p[0], +p[1]-1, +p[2]); };
  const fmt = (d) => d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
  const add = (days) => { const d = base(); d.setDate(d.getDate() + days); return fmt(d); };
  const meses = { enero: 1, febrero: 2, marzo: 3, abril: 4, mayo: 5, junio: 6, julio: 7, agosto: 8, septiembre: 9, setiembre: 9, octubre: 10, noviembre: 11, diciembre: 12 };
  const tryParse = (s) => {
    if (!s) return null;
    const m1 = s.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
    if (m1) return m1[1] + '-' + String(+m1[2]).padStart(2, '0') + '-' + String(+m1[3]).padStart(2, '0');
    const m2 = s.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    if (m2) return m2[3] + '-' + String(+m2[2]).padStart(2, '0') + '-' + String(+m2[1]).padStart(2, '0');
    const m3 = s.match(/(\d{1,2})\s*(?:de\s+)?([a-záéíóúñ]+)(?:\s+de\s+(\d{4}))?/i);
    if (m3 && meses[m3[2].toLowerCase()]) {
      const anio = m3[3] ? +m3[3] : base().getFullYear();
      return anio + '-' + String(meses[m3[2].toLowerCase()]).padStart(2,'0') + '-' + String(+m3[1]).padStart(2,'0');
    }
    const m4 = s.match(/(\d{1,2})\/(\d{1,2})(?!\/)/);
    if (m4) {
      const hoy = base();
      let d = new Date(hoy.getFullYear(), +m4[2]-1, +m4[1]);
      if (d < hoy) d = new Date(hoy.getFullYear()+1, +m4[2]-1, +m4[1]);
      return fmt(d);
    }
    const m6 = s.match(/^\s*(\d{1,2})\s*$/);
    if (m6) {
      const hoy = base();
      let d = new Date(hoy.getFullYear(), hoy.getMonth(), +m6[1]);
      if (d < hoy) d = new Date(hoy.getFullYear(), hoy.getMonth()+1, +m6[1]);
      return fmt(d);
    }
    const m5 = s.match(/\bel\s+(\d{1,2})\b/);
    if (m5) {
      const hoy = base();
      let d = new Date(hoy.getFullYear(), hoy.getMonth(), +m5[1]);
      if (d < hoy) d = new Date(hoy.getFullYear(), hoy.getMonth()+1, +m5[1]);
      return fmt(d);
    }
    return null;
  };
  const raw = String($('AI Agent').item.json.output.datos_reserva.fecha || '').trim();
  const user = String(($('Edit Fields - Salto de linea').first().json.chat_input) || '').toLowerCase();
  const text = (raw + ' ' + user).toLowerCase();
  const parsed = tryParse(raw) || tryParse(user);
  if (parsed) return parsed;
  if (text.includes('pasado mañana') || text.includes('pasado manana')) return add(2);
  if (text.includes('pasado') || text.includes('pasada')) return add(2);
  if (text.includes('mañana') || text.includes('manana')) return add(1);
  if (text.includes('hoy')) return arg();
  const semana = { domingo: 0, lunes: 1, martes: 2, miercoles: 3, jueves: 4, viernes: 5, sabado: 6 };
  for (const [nombre, idx] of Object.entries(semana)) {
    if (text.includes(nombre)) {
      const d = base();
      const hoyIdx = d.getDay();
      let delta = (idx - hoyIdx + 7) % 7;
      if (delta === 0) delta = 7;
      d.setDate(d.getDate() + delta);
      return fmt(d);
    }
  }
  return arg();
})() }}

