const raw = $('Get Carta').item.json;

const FALLO = 'El menú no está disponible en este momento. Si el cliente pide recomendaciones o quiere conocer platos y precios, compartile el enlace de la carta: https://andirestaurante.com.ar/nuestra-carta/';

let html = '';
try {
  if (Array.isArray(raw)) {
    html = raw[0]?.content?.rendered || '';
  } else if (raw?.content?.rendered) {
    html = raw.content.rendered;
  } else if (raw?.error) {
    html = '';
  } else if (raw && typeof raw === 'object') {
    const found = Object.values(raw).find(x => x && typeof x === 'object' && x.content && x.content.rendered);
    if (found) html = found.content.rendered;
  }
} catch (e) {}

if (!html || html.length < 200) {
  return [{ json: { carta: FALLO, carta_disponible: false } }];
}

let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<br[^>]*>/gi, '\n')
  .replace(/<\/(?:p|div|section|h[1-6]|li|tr|ul|ol|article)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&#8211;|&ndash;/gi, '–')
  .replace(/&#8217;|&rsquo;/gi, "'")
  .replace(/&[a-z]+;/gi, ' ')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n[ \t]+/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (text.length < 200) {
  return [{ json: { carta: FALLO, carta_disponible: false } }];
}

return [{ json: { carta: text, carta_disponible: true } }];

const parse = $('Parse Cancelación').item.json;
const raw = $('Get Reservas Para Cancelar').item.json;

const extractDocuments = (data) => {
  if (!data) return [];
  if (Array.isArray(data)) return data;
  if (data.documents && Array.isArray(data.documents)) return data.documents;
  if (data.items && Array.isArray(data.items)) return data.items;
  if (data.body) return extractDocuments(data.body);
  if (data.data) return extractDocuments(data.data);
  return [];
};

const extractField = (item, key) => {
  if (!item) return null;
  if (item.document) item = item.document;
  if (item.fields && item.fields[key]) {
    const f = item.fields[key];
    return f.stringValue !== undefined ? f.stringValue :
           f.integerValue !== undefined ? parseInt(f.integerValue) :
           f.booleanValue !== undefined ? f.booleanValue :
           f.doubleValue !== undefined ? parseFloat(f.doubleValue) : null;
  }
  return item[key] !== undefined ? item[key] : null;
};

const extractId = (item) => {
  if (!item) return '';
  if (item.id) return item.id;
  if (item.name) return item.name.split('/').pop();
  return '';
};

const normalizePhone = (v) => {
  if (!v) return '';
  let s = String(v).replace(/@s\.whatsapp\.net$/i, '').replace(/[^0-9]/g, '');
  if (!s) return '';
  if (s.startsWith('0')) s = s.slice(1);
  if (s.startsWith('54')) return s;
  const m = s.match(/^(\d{2,4})15(\d{6,8})$/);
  if (m) s = m[1] + '9' + m[2];
  return '54' + s;
};

const phone = normalizePhone(parse.cancel_telefono);
const nombre = String(parse.cancel_nombre || '').trim().toLowerCase();

const docs = extractDocuments(raw);
const candidates = docs
  .map(d => ({
    id: extractId(d),
    customerPhone: normalizePhone(extractField(d, 'customerPhone') || extractField(d, 'phone')),
    name: String(extractField(d, 'customerName') || '').trim().toLowerCase(),
    estado: extractField(d, 'estado') || '',
    date: extractField(d, 'date') || '',
    tableId: extractField(d, 'tableId') || extractField(d, 'mesa_id') || '',
    service: extractField(d, 'service') || '',
    createdAt: extractField(d, 'createdAt') || '',
  }))
  .filter(r => ['pendiente', 'confirmada'].includes(r.estado))
  .filter(r => (phone && r.customerPhone === phone) || (nombre && r.name === nombre));

candidates.sort((a, b) => (b.createdAt || '') > (a.createdAt || '') ? 1 : -1);
const found = candidates[0] || null;

return [{
  json: {
    found: !!found,
    reservation_id: found ? found.id : '',
    mesa_res_id: found && found.tableId && found.date && found.service ? found.tableId + '_' + found.date + '_' + found.service : '',
  }
}];
